const X=window.CivicExplain;
const REDUCED=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches);
const SMOOTH=REDUCED?'auto':'smooth';
const PRE_MOVE_MS=1500; // the interpretation is shown before the walk starts
let walkTimers=[],currentResult=null,coach=null;
function announce(t){const a=document.getElementById('announcer');if(!a)return;a.textContent='';setTimeout(()=>{a.textContent=t},30)}
function cancelWalk(){walkTimers.forEach(clearTimeout);walkTimers=[];document.body.classList.remove('walking');const o=document.getElementById('nbresult');if(o&&o.dataset.navigation!=='complete'){o.dataset.navigation='cancelled';const ns=o.querySelector('.navstage span');if(ns)ns.textContent='Stopped. You can carry on browsing from here.'}const sw=document.getElementById('stopwalk');if(sw)sw.remove();document.getElementById('trace').classList.remove('show');stripHide();announce('Navigation stopped.')}
function routeLabels(id,section){const s=byId(id),d=dom(s.domain),parent=s.parent?byId(s.parent):null;const L=[{label:'Home',hash:'#home'},{label:d[1],hash:`#domain/${s.domain}`},{label:s.group,hash:`#group/${s.domain}/${encodeURIComponent(s.group)}`}];if(parent)L.push({label:parent.title,hash:`#service/${parent.id}`});L.push({label:s.title,hash:`#service/${id}`});if(section!=null)L.push({label:s.sections[section].label,hash:`#service/${id}/section/${section}`});return L}
function routeStrip(L,active,opts={}){return `<ol class="route${opts.mini?' mini':''}"${opts.label?` aria-label="${escape(opts.label)}"`:''}>${L.map((x,i)=>`<li class="${i<active?'done':i===active?'active':'todo'}"${i===active?' aria-current="step"':''}>${escape(x.label)}</li>`).join('')}</ol>`}
function walkCard(kicker,L,active,caption){return `<div class="tiny">${escape(kicker)}</div>${routeStrip(L,active)}<span class="walkcap">${escape(caption)}</span>`}
/* navigateTo: identical hash sequence, 600 ms step timing, trace strings, logs and dataset flags to RESOLVER6; new visuals only. */
function navigateTo(id,section,source){
 const v=C.validateDestination(id,section);
 if(!v.ok){console.warn('CivicSphereNav blocked navigation:',v.error);log('navigation_blocked',{destination:id,section,error:v.error});toast('Destination could not be validated against the catalogue.');const o=document.getElementById('nbresult');if(o)o.dataset.navigation='blocked';return false}
 walkTimers.forEach(clearTimeout);walkTimers=[];exitCoach(true);setPanel(false);
 const s=byId(id),d=dom(s.domain),parent=s.parent?byId(s.parent):null,finalPath=C.pathLabels(id,section);
 const L=routeLabels(id,section),N=L.length;
 const steps=[{hash:`#domain/${s.domain}`,plain:d[1],ev:'navigation_domain',cap:d[3]==='account'?'Opening your account':'Entering the topic'},{hash:`#group/${s.domain}/${encodeURIComponent(s.group)}`,plain:s.group,ev:'navigation_group',cap:'Choosing the group'}];
 if(parent)steps.push({hash:`#service/${parent.id}`,plain:parent.title,ev:'navigation_parent',cap:'Opening '+parent.title});
 steps.push({hash:`#service/${id}`,plain:s.title,ev:'navigation_service',cap:'Opening the service page'});
 document.body.classList.add('walking');
 stripRender(L,0,'Starting from the homepage',true);setTrace(walkCard('CivicSphereNav is taking you there',L,0,'Starting from the homepage'),'Understanding goal');log('navigation_started',{destination:id,section,source});announce(`Taking you to ${finalPath[finalPath.length-1]}. ${N-1} steps.`);
 steps.forEach((st,i)=>walkTimers.push(setTimeout(()=>{location.hash=st.hash;stripRender(L,i+1,`Step ${i+1} of ${N-1} · ${st.cap}`,true);setTrace(walkCard('CivicSphereNav is taking you there',L,i+1,`Step ${i+1} of ${N-1} · ${st.cap}`),st.plain);announce(`Step ${i+1} of ${N-1}: ${st.plain}`);log(st.ev,{destination:id})},600*(i+1))));
 walkTimers.push(setTimeout(()=>{location.hash=`#service/${id}${section!=null?'/usher/sites/civicsphere/section/'+section:''}`;stripRender(L,N-1,'You are here: '+finalPath[finalPath.length-1],false);setTrace(walkCard('Found it',L,N,finalPath.join(' → ')),'FOUND: '+finalPath.join(' → '));document.body.classList.remove('walking');log('navigation_completed',{destination:id,section,source});
  const o=document.getElementById('nbresult');if(o){o.dataset.navigation='complete';const ns=o.querySelector('.navstage span');if(ns)ns.textContent='Navigation complete';const sw=document.getElementById('stopwalk');if(sw)sw.remove();afterArrival(o,id,section)}
  announce(`Arrived: ${finalPath[finalPath.length-1]}.${section!=null?' The section is highlighted.':''}`);
  if(window.matchMedia&&matchMedia('(max-width:760px)').matches){setPanel(false);toast('Arrived: '+finalPath[finalPath.length-1])}
  walkTimers.push(setTimeout(()=>document.getElementById('trace').classList.remove('show'),2400))},600*(steps.length+1)));
 return true;
}
