function situationHtml(r){const items=X.situation(C,r);return items.map(it=>`<div class="situation" role="note"><span class="kicker">Something of yours</span><p>You have a saved ${escape(it.subject?it.subject.replace(/^a /,''):it.serviceTitle)} application (ref ${escape(it.reference)}). Continue from step ${it.stepNo} of ${it.total}, ${escape(it.stepLabel)}?</p><button class="btn secondary situbtn" type="button" data-saved="${it.savedId}">Continue application</button></div>`).join('')}
function afterArrival(o,id,section){const ex=document.getElementById('rsextra');if(!ex||ex.querySelector('.arrival'))return;const r=currentResult;const box=document.createElement('div');box.className='arrival';
 box.innerHTML=`<button class="btn secondary howbtn" type="button" id="howbtn">Show me how to find this myself next time</button>${r&&r.decision==='navigate'?situationHtml(r):''}`;
 ex.appendChild(box);box.querySelector('#howbtn').onclick=()=>startCoach(id,section)}
function bridgeHtml(b){if(!b)return '';const li=[];if(b.page)li.push(`You said “${escape(b.page.phrase)}”: on this site that’s called <b>${escape(b.page.label)}</b>${b.page.area?` (in ${escape(b.page.area)})`:''}.`);if(b.section)li.push(`You said “${escape(b.section.phrase)}”: on this page that’s under <b>${escape(b.section.label)}</b>.`);return `<ul class="bridge" aria-label="Terminology">${li.map(x=>`<li>${x}</li>`).join('')}</ul>`}
