const EXAMPLES=['I need a new passport',"I've just moved into a new house and need to sort out parking. I want to know what I'll have to pay.",'my landlord won’t fix the damp in my flat'];
function renderDecision(r,source){
 currentResult=r;
 const dbg=(r.fallbackNotice?`<p class="fallbacknote" id="fallbacknote">${escape(r.fallbackNotice)}</p>`:'')+(DEBUG?(r.mode==='semantic'?semanticDebugHtml(r):debugHtml(r)):'');
 const it=X.interpret(C,r);
 if(r.decision==='navigate'){const s=byId(r.destinationId);const v=C.validateDestination(r.destinationId,r.sectionIndex);if(!v.ok){setResult('<div class="badge">Navigation blocked</div><h3>The resolved destination failed catalogue validation.</h3>'+dbg,{decision:'blocked'});console.warn('Blocked invalid destination',v.error);return}
  const L=routeLabels(r.destinationId,r.sectionIndex);
  setResult(`<div class="answer"><span class="kicker">What I understood</span><p class="interp">${escape(it?it.text:'')}</p>${bridgeHtml(X.bridge(C,r))}<div class="dest"><span class="kicker">Taking you to</span><h3>${escape(s.title)}${r.sectionLabel?' · '+escape(r.sectionLabel):''}</h3>${routeStrip(L,-1,{mini:true,label:'Route'})}</div>${whyHtml(X.whyHere(C,r))}<div class="walkrow"><div class="navstage active"><i></i><span>Taking you there…</span></div><button class="linkbtn" type="button" id="stopwalk">Stop</button></div><p class="conf">Goal resolved · ${Math.round(r.confidence*100)}% confidence</p></div>${dbg}`,{decision:'navigate',destination:r.destinationId,section:r.sectionIndex});fixDebug();
  announce((it?it.text+' ':'')+'Taking you to '+s.title+(r.sectionLabel?', '+r.sectionLabel:'')+'.');
  walkTimers.push(setTimeout(()=>navigateTo(r.destinationId,r.sectionIndex,source),PRE_MOVE_MS));return}
 const c=X.clarifyQuestion(r);
 if(r.decision==='clarify'){const opts=c.options.length?`<div class="optlist question" role="group" aria-labelledby="askq-h">${c.options.map(o=>`<button class="optbtn" type="button" data-id="${o.id}" data-section="${o.sectionIndex==null?'':o.sectionIndex}"><span class="opttitle">${escape(o.title)}</span><small>${escape(o.path)}</small></button>`).join('')}</div>`:'';
  setResult(`<div class="askq"><span class="kicker">What I understood</span><p class="interp">${escape(it?it.text:'')}</p><span class="kicker">One quick question</span><h3 id="askq-h">${escape(c.question)}</h3>${opts}<p class="mini">${c.options.length?'Not quite right? Describe it a different way.':'Add a little more detail and try again.'}</p></div>${situationHtml(r)}${dbg}`,{decision:'clarify'});fixDebug();
  announce((it?it.text+' ':'')+c.question+(c.options.length?` ${c.options.length} options.`:''));return}
 const msg=(r.clarification&&r.clarification.message)||'I could not resolve that goal to a CivicSphere destination.';
 setResult(`<div class="notice reject"><span class="kicker">What I understood</span><p class="interp">${escape(it?it.text:'')}</p><p>${escape(msg)}</p></div><p class="mini">You could try one of these:</p><div class="eglist">${EXAMPLES.slice(0,2).map(q=>`<button class="egbtn" type="button" data-q="${escape(q)}">${escape(q.length>60?q.slice(0,57)+'…':q)}</button>`).join('')}</div>${dbg}`,{decision:'reject'});fixDebug();
 announce(msg);
}
/* ---- "Show me how to find this myself": replays the route as real menu clicks ---- */
function coachSteps(id,section){const s=byId(id),d=dom(s.domain),parent=s.parent?byId(s.parent):null;const G=`#group/${s.domain}/${encodeURIComponent(s.group)}`;
 const st=[{at:'#home',href:`#domain/${s.domain}`,text:d[3]==='account'?'Select “My account” at the top of the page.':`On the homepage, choose “${d[1]}”.`},{at:`#domain/${s.domain}`,href:G,text:`Choose “${s.group}”.`},{at:G,href:`#service/${parent?parent.id:id}`,text:`Choose “${parent?parent.title:s.title}”.`}];
 if(parent)st.push({at:`#service/${parent.id}`,href:`#service/${id}`,prefix:true,text:`Open “${s.title}”.`});
 if(section!=null)st.push({at:`#service/${id}`,href:`#service/${id}/section/${section}`,toc:true,text:`In “Contents”, choose “${s.sections[section].label}”.`});
 return st}
function coachTarget(step){const as=[...document.querySelectorAll(step.toc?'.toc a':'a')].filter(a=>{const h=a.getAttribute('href')||'';return step.prefix?h.startsWith(step.href):h===step.href});return as.find(a=>a.offsetParent!==null)||as[0]||null}
function startCoach(id,section){cancelWalk();exitCoach(true);coach={id,section,steps:coachSteps(id,section),i:0,final:`#service/${id}${section!=null?'/usher/sites/civicsphere/section/'+section:''}`};setPanel(false);
 const box=document.getElementById('coach');box.hidden=false;log('coach_started',{destination:id,section});
 if(location.hash!==coach.steps[0].at)location.hash=coach.steps[0].at;else showCoach()}
function showCoach(){if(!coach)return;const box=document.getElementById('coach');document.querySelectorAll('.coach-target').forEach(e=>e.classList.remove('coach-target'));
 if(location.hash===coach.final||coach.i>=coach.steps.length){box.innerHTML=`<p class="kicker">Find it yourself</p><p id="coachtext"><b>That’s the route.</b> Next time, follow the same menus: ${escape(routeLabels(coach.id,coach.section).map(x=>x.label).join(' › '))}.</p><div class="coachbtns"><button class="btn primary" type="button" id="coachdone">Done</button></div>`;document.getElementById('coachdone').onclick=()=>exitCoach();document.getElementById('coachdone').focus();announce('That is the route. '+routeLabels(coach.id,coach.section).map(x=>x.label).join(', then '));return}
 const st=coach.steps[coach.i];const t=coachTarget(st);
 box.innerHTML=`<p class="kicker">Find it yourself · step ${coach.i+1} of ${coach.steps.length}</p><p id="coachtext">${escape(st.text)}${t?'':' (link not visible on this page)'}</p><div class="coachbtns"><button class="btn primary" type="button" id="coachnext">${t?'Do it for me':'Next'}</button><button class="linkbtn" type="button" id="coachstop">Stop</button></div>`;
 document.getElementById('coachnext').onclick=()=>{coach.i++;location.hash=st.href};document.getElementById('coachstop').onclick=()=>exitCoach();
 if(t){t.classList.add('coach-target');t.scrollIntoView({behavior:SMOOTH,block:'center'});setTimeout(()=>t.focus({preventScroll:true}),REDUCED?0:250)}
 announce(`Step ${coach.i+1} of ${coach.steps.length}. ${st.text}`)}
function coachOnRoute(){if(!coach)return;const h=location.hash;const idx=coach.steps.findIndex(s=>s.at===h);if(h===coach.final)coach.i=coach.steps.length;else if(idx>=0)coach.i=idx;else{exitCoach(true);return}setTimeout(showCoach,60)}
function exitCoach(silent){document.querySelectorAll('.coach-target').forEach(e=>e.classList.remove('coach-target'));const box=document.getElementById('coach');if(box){box.hidden=true;box.innerHTML=''}if(coach&&!silent)announce('Guide closed.');coach=null}
/* ---- keyword site search (BM25 over each page's visible text) ---- */
let SEARCH=null;
const stripTags=h=>String(h).replace(/<[^>]+>/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&#39;/g,"'").replace(/&quot;/g,'"').replace(/\s+/g,' ').trim();
function factsText(s){if(dom(s.domain)[3]==='account')return '';const f=SITE.facts(s);return [f.fee,f.time,...(f.who||[]),...(f.need||[]),...((f.fees||[]).map(r=>r.join(' ')))].filter(Boolean).join('. ')}
function visibleDoc(s){return {id:s.id,title:s.title,group:s.group,domainLabel:dom(s.domain)[1],summary:s.description,intro:[(s.about||[]).join(' '),factsText(s)].filter(Boolean).join(' '),sections:s.sections.map((x,i)=>({id:x.id,label:x.label,body:stripTags(sectionBody(s,x,i))}))}}
function searchIndex(){if(!SEARCH){const docs=SERVICES.filter(s=>CivicSemantic.routable(s)).map(visibleDoc);SEARCH={engine:CivicSearch.build(C,docs),docs:new Map(docs.map(d=>[d.id,d]))}}return SEARCH}
function markTerms(text,terms){const T=new Set(terms);return escape(text).replace(/[A-Za-z][A-Za-z']*/g,w=>{const n=C.normalise(w);return n&&T.has(C.stem(n))?`<mark>${w}</mark>`:w})}
function snippetFor(d,res,terms){const T=new Set(terms);const pool=[];if(res.sectionIndex!=null)pool.push(d.sections[res.sectionIndex].body);pool.push(d.summary,d.intro,...d.sections.map(x=>x.body));
 let best=null;for(const txt of pool){for(const sent of String(txt||'').split(/(?<=[.!?])\s+/)){const hits=C.normalise(sent).split(' ').filter(w=>T.has(C.stem(w))).length;if(!best||hits>best.hits)best={sent,hits}}if(best&&best.hits>1)break}
 let t=(best&&best.sent)||d.summary;if(t.length>200){t=t.slice(0,200);t=t.slice(0,t.lastIndexOf(' '))+'…'}return markTerms(t,terms)}
function keywordResults(q,k){const S=searchIndex();const out=S.engine.search(q,k);return {...out,items:out.results.map(r=>{const d=S.docs.get(r.id),s=byId(r.id);return {r,d,s,path:['Home',dom(s.domain)[1],s.group].concat(s.parent?[byId(s.parent).title]:[]),snippet:snippetFor(d,r,out.terms)}})}}
function resultsHtml(q,k){const R=keywordResults(q,k);if(!R.items.length)return '<div class="notice">No pages matched your search. Try different words.</div>';
 return `<p class="vsmeta">${R.total} result${R.total===1?'':'s'} for “${escape(q)}”${R.total>R.items.length?` · showing ${R.items.length}`:''}</p><ol class="results">${R.items.map(x=>`<li class="searchresult"><h3><a href="#service/${x.s.id}">${escape(x.s.title)}</a></h3><p class="rpath">${x.path.map(escape).join(' › ')}</p><p class="rsnip">${x.snippet}</p></li>`).join('')}</ol>`}
function searchPage(q=''){const initial=q||'';
 return `<div class="container">${crumbs([['Home','#home'],['Search',null]])}<h1>Search this site</h1><form class="directory-tools" onsubmit="event.preventDefault();location.hash='#search/'+encodeURIComponent(document.getElementById('searchBox').value)"><label class="visually-hidden" for="searchBox">Search this site</label><input id="searchBox" type="search" value="${escape(initial)}"><button class="btn primary" type="submit">Search</button></form>${initial?'':'<p class="muted">Enter a word or phrase, such as “replace identity document” or “parking cost”.</p>'}<h2 class="visually-hidden">Results</h2><div id="searchResults" class="section">${initial?resultsHtml(initial,10):''}</div></div>`}
/* ---- comparison mode: keyword site search (left) vs CivicSphereNav (right) on the same query ---- */
const VS_EXAMPLES=['I need a new passport',"I've just moved into a new house and need to sort out parking. I want to know what I'll have to pay.",'my landlord won’t fix the damp in my flat','I want to appeal'];
function versusPage(q){const n=searchIndex().engine.size;
 return `<div class="container versus">${crumbs([['Home','#home'],['Compare with site search',null]])}<div class="vshead"><div><h1>Site search and CivicSphereNav, side by side</h1><p class="lead">The same question, answered two ways, over the same ${n} pages.</p></div><a class="linkbtn exitvs" href="#home">Exit comparison</a></div>
 <form class="vsform" onsubmit="event.preventDefault();location.hash='#versus/'+encodeURIComponent(document.getElementById('vsq').value)"><label for="vsq">Your question</label><div class="vsrow"><input id="vsq" value="${escape(q||'')}" autocomplete="off" placeholder="Describe what you need in your own words"><button class="btn primary" type="submit">Compare</button></div>
 <div class="vsexamples"><span>Try:</span>${VS_EXAMPLES.map(e=>`<a href="#versus/${encodeURIComponent(e)}">${escape(e.length>48?e.slice(0,45)+'…':e)}</a>`).join('')}</div></form>
 <div class="vsgrid"><section class="vspane" aria-labelledby="vs-s-h"><h2 id="vs-s-h">Site search <span class="modebadge">keyword search</span></h2><div id="vsSearch">${q?resultsHtml(q,6):'<p class="muted">Results appear here.</p>'}</div></section>
 <section class="vspane nav" aria-labelledby="vs-n-h"><h2 id="vs-n-h">CivicSphereNav <span class="modebadge">goal-based</span></h2><div id="vsNav" aria-live="polite">${q?'<div class="navstage active"><i></i><span>Understanding your goal…</span></div>':'<p class="muted">The interpretation and route appear here.</p>'}</div></section></div>
 <p class="vsnote">Left: a conventional council site search. Okapi BM25 ranking over each page’s visible text (title, breadcrumb, summary, headings and section text), the same keyword baseline as the CivicSphereNav evaluation. Right: CivicSphereNav’s single committed answer from the same pages, with its interpretation, route and evidence. Both run locally in your browser.</p></div>`}
let vsToken=0;
async function runVersus(q){const box=document.getElementById('vsNav');if(!box||!q)return;const tok=++vsToken;let res;try{res=await semanticResult(q)}catch(e){console.error(e);box.innerHTML='<p>CivicSphereNav could not interpret that.</p>';return}
 if(location.hash!=='#versus/'+encodeURIComponent(q)&&decodeURIComponent(location.hash.slice(8))!==q)return;
 const r=res.r,it=X.interpret(C,r);let h=`<p class="interp">${escape(it?it.text:'')}</p>`;
 if(r.decision==='navigate'){const s=byId(r.destinationId),L=routeLabels(r.destinationId,r.sectionIndex);h+=`${bridgeHtml(X.bridge(C,r))}<div class="dest"><span class="kicker">One answer</span><h3>${escape(s.title)}${r.sectionLabel?' · '+escape(r.sectionLabel):''}</h3><div id="vsroute">${routeStrip(L,REDUCED?L.length:0,{label:'Route'})}</div></div>${whyHtml(X.whyHere(C,r))}${situationHtml(r)}<button class="btn primary" type="button" id="vsgo">Take me there</button>`;
  box.innerHTML=h;box.querySelectorAll('.situbtn').forEach(sb=>sb.onclick=()=>{log('situation_continue',{saved:sb.dataset.saved,source:'compare'});resumeSaved(sb.dataset.saved)});document.getElementById('vsgo').onclick=()=>{setPanel(true);currentResult=r;setResult(`<div class="answer"><p class="interp">${escape(it?it.text:'')}</p><div class="dest"><span class="kicker">Taking you to</span><h3>${escape(s.title)}${r.sectionLabel?' · '+escape(r.sectionLabel):''}</h3></div><div class="walkrow"><div class="navstage active"><i></i><span>Taking you there…</span></div></div></div>`,{decision:'navigate',destination:r.destinationId,section:r.sectionIndex});navigateTo(r.destinationId,r.sectionIndex,'compare')};
  if(!REDUCED){let i=0;const tick=()=>{const el=document.getElementById('vsroute');if(!el||tok!==vsToken)return;i++;el.innerHTML=routeStrip(L,i,{label:'Route'});if(i<L.length)setTimeout(tick,450)};setTimeout(tick,450)}}
 else if(r.decision==='clarify'){const c=X.clarifyQuestion(r);h+=`<div class="askq"><span class="kicker">One quick question</span><h3>${escape(c.question)}</h3><div class="optlist question">${c.options.map(o=>`<a class="optlink" href="#service/${o.id}${o.sectionIndex!=null?'/usher/sites/civicsphere/section/'+o.sectionIndex:''}"><span class="opttitle">${escape(o.title)}</span><small>${escape(o.path)}</small></a>`).join('')}</div></div>`;box.innerHTML=h}
 else{h+=`<div class="notice reject"><p>${escape((r.clarification&&r.clarification.message)||'')}</p></div>`;box.innerHTML=h}
 if(r.fallbackNotice)box.insertAdjacentHTML('beforeend',`<p class="fallbacknote">${escape(r.fallbackNotice)}</p>`);log('compare_view',{query:q,decision:r.decision,destination:r.destinationId,keywordTop:(keywordResults(q,1).items[0]||{s:{}}).s.id})}
/* ---------------- frame behaviour ---------------- */
function setPanel(open,focus){const p=document.getElementById('nbpanel'),pill=document.getElementById('nbpill'),was=p.classList.contains('open');if(!open&&p.contains(document.activeElement))pill.focus();p.classList.toggle('open',open);document.getElementById('nbscrim').hidden=!open;document.body.classList.toggle('assist-open',open);pill.setAttribute('aria-expanded',String(open));if(open&&(focus||!was))document.getElementById('nbinput').focus()}
function panelFocusables(){return[...document.querySelectorAll('#nbpanel button,#nbpanel input,#nbpanel a[href],#nbpanel [tabindex="0"]')].filter(e=>!e.disabled&&e.offsetParent!==null)}
function stripHide(){const el=document.getElementById('routestrip');if(el){el.hidden=true;el.innerHTML=''}}
function stripRender(L,active,caption,walking){const el=document.getElementById('routestrip');if(!el)return;const keep=document.getElementById('rsextra');const extra=keep&&!walking?keep.innerHTML:'';
 el.hidden=false;el.dataset.state=walking?'walking':'arrived';
 el.innerHTML=`<div class="rshead"><strong>Your route</strong><span class="rscap">${escape(caption)}</span>${walking?'<button class="linkbtn" type="button" id="stripstop">Stop</button>':''}<button class="rsx" type="button" id="rsdismiss" aria-label="Dismiss your route">Dismiss <span aria-hidden="true">×</span></button></div><ol class="rsl">${L.map((x,i)=>`<li class="${i<active?'done':i===active?'active':'todo'}"${i===active?' aria-current="step"':''}><span class="rsn" aria-hidden="true">${i+1}</span>${escape(x.label)}</li>`).join('')}</ol><div id="rsextra">${extra}</div>`;
 document.getElementById('rsdismiss').onclick=()=>{if(document.body.classList.contains('walking'))cancelWalk();stripHide();log('route_strip_dismissed')};
 const st=document.getElementById('stripstop');if(st)st.onclick=()=>cancelWalk()}
function toggleMenu(b){const n=document.getElementById('primary-nav');const o=!n.classList.contains('open');n.classList.toggle('open',o);b.setAttribute('aria-expanded',String(o))}
function cookieChoice(c){document.getElementById('cookie-banner').hidden=true;toast(c==='accepted'?'You accepted analytics cookies (demonstration only).':'You rejected analytics cookies (demonstration only).');log('cookie_banner_'+c)}
function fillOrg(){const o=SITE.ORG;document.querySelectorAll('[data-org]').forEach(el=>{const k=el.dataset.org;el.textContent=k==='address'?o.address.join(', '):o[k]});document.getElementById('footer-version').textContent='Research prototype · '+C.VERSION+' resolver · UI R6.3'}
function render(){let h=location.hash.slice(1)||'home';const p=h.split('/usher/sites/civicsphere/');let c;
 try{
  if(p[0]==='home')c=home();else if(p[0]==='directory')c=directory();else if(p[0]==='search')c=searchPage(p[1]?decodeURIComponent(p.slice(1).join('/usher/sites/civicsphere/')):'');else if(p[0]==='compare')c=comparePage();else if(p[0]==='versus')c=versusPage(p[1]?decodeURIComponent(p.slice(1).join('/usher/sites/civicsphere/')):'');else if(p[0]==='domain')c=domainPage(p[1]);else if(p[0]==='group')c=groupPage(p[1],decodeURIComponent(p.slice(2).join('/usher/sites/civicsphere/')));else if(p[0]==='service')c=servicePage(p[1],p[2]==='section'?p[3]:null);
  else if(p[0]==='task'){const t=C.TASKS[p[1]];if(!t)c=notFound('task '+p[1]);else{state.task=p[1];const st=parseInt(p[2],10);state.taskStep=Number.isInteger(st)&&st>=0&&st<t.steps.length?st:0;state.resumed=p[3]==='resumed';c=taskPage(p[1])}}
  else if(p[0]==='info')c=infoPage(p[1]);else if(p[0]==='about')c=aboutPage();else c=home();
 }catch(e){console.error('CivicSphere render error:',e);c=notFound(h)}
 document.getElementById('app').innerHTML=c;wire();document.body.classList.toggle('compare-view',p[0]==='versus');if(p[0]==='versus'&&p[1])runVersus(decodeURIComponent(p.slice(1).join('/usher/sites/civicsphere/')));if(coach)coachOnRoute();
 const h1=document.querySelector('#app h1');document.title=(h1&&p[0]!=='home'?h1.textContent+' - ':'')+'CivicSphere City Council';
 if(p[0]==='service'&&p[2]==='section'){setTimeout(()=>{const e=document.getElementById('sec-'+p[3]);if(e){e.scrollIntoView({behavior:SMOOTH,block:'center'});e.classList.add('dest-highlight');e.dataset.highlighted='1';setTimeout(()=>e.classList.remove('dest-highlight'),3000)}},650)}}
function wire(){const vt=document.getElementById('vstoggle');if(vt)vt.onclick=()=>{setPanel(false);location.hash='#versus'};document.getElementById('nbpill').onclick=()=>setPanel(!document.getElementById('nbpanel').classList.contains('open'),true);document.getElementById('nbclose').onclick=()=>{setPanel(false);document.getElementById('nbpill').focus()};document.getElementById('nbscrim').onclick=()=>{setPanel(false);document.getElementById('nbpill').focus()};document.getElementById('nbfind').onclick=()=>resolve(document.getElementById('nbinput').value);document.getElementById('mic').onclick=voice;document.getElementById('nbinput').onkeydown=e=>{if(e.key==='Enter')resolve(e.target.value)}}
document.getElementById('nbresult').addEventListener('click',e=>{const sb=e.target.closest('.situbtn');if(sb){log('situation_continue',{saved:sb.dataset.saved});resumeSaved(sb.dataset.saved);return}const eg=e.target.closest('.egbtn');if(eg){document.getElementById('nbinput').value=eg.dataset.q;resolve(eg.dataset.q);return}if(e.target.closest('#stopwalk')){cancelWalk();return}const b=e.target.closest('.optbtn');if(!b)return;const sec=b.dataset.section===''?null:Number(b.dataset.section);log('clarification_option_chosen',{destination:b.dataset.id,section:sec});navigateTo(b.dataset.id,sec,'clarification-choice')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&coach){exitCoach();return}if(e.key==='Escape'&&document.getElementById('nbpanel').classList.contains('open')){setPanel(false);document.getElementById('nbpill').focus()}});
document.addEventListener('keydown',e=>{const p=document.getElementById('nbpanel');const open=p.classList.contains('open');
 if(e.key==='/usher/sites/civicsphere/'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!open){const t=e.target,tag=t&&t.tagName;if(tag==='INPUT'||tag==='TEXTAREA'||tag==='SELECT'||(t&&t.isContentEditable))return;e.preventDefault();setPanel(true,true);return}
 if(e.key==='Tab'&&open){const f=panelFocusables();if(!f.length)return;const first=f[0],last=f[f.length-1];if(!p.contains(document.activeElement)){e.preventDefault();first.focus()}else if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
document.getElementById('routestrip').addEventListener('click',e=>{const sb=e.target.closest('.situbtn');if(sb){log('situation_continue',{saved:sb.dataset.saved});resumeSaved(sb.dataset.saved)}});
if(DEBUG){document.getElementById('nbpanel').classList.add('debug');document.body.classList.add('debug-open');setPanel(true)}
fillOrg();
if(new URLSearchParams(location.search).get('compare')==='1'&&(!location.hash||location.hash==='#home'))history.replaceState(null,'','#versus');
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:SMOOTH})});render();log('session_started',{version:C.VERSION,catalogueValid:CATALOGUE_CHECK.ok});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bootEmbedderStatus);else bootEmbedderStatus();
